import assert from 'node:assert/strict';
import test from 'node:test';
import { readFileSync } from 'node:fs';

const webAppSource = readFileSync(new URL('../../../web/app.js', import.meta.url), 'utf8');
const stylesSource = readFileSync(new URL('../../../web/styles.css', import.meta.url), 'utf8');

test('atlas renders compatibility bundles for climate rebound follow-up queues', () => {
  assert.match(webAppSource, /buildAtlasClimateFollowUpCompatibilityBundles/);
  assert.match(webAppSource, /renderAtlasClimateFollowUpCompatibilityBundles/);
  assert.match(webAppSource, /Compatibilité suivis climat/);
  assert.match(webAppSource, /Minimal sûr/);
  assert.match(webAppSource, /Ambitieux fragile/);
  assert.match(webAppSource, /cooling-off-timing/);
  assert.match(webAppSource, /regional-residual-risk/);
  assert.match(webAppSource, /À laisser en attente si minimal/);
  assert.match(webAppSource, /Delta risque/);
  assert.match(webAppSource, /worsening-probable/);
  assert.match(webAppSource, /stable-risk/);
  assert.match(webAppSource, /reduced/);
  assert.match(webAppSource, /delta inconnu/);
  assert.match(webAppSource, /Calendrier cooldown/);
  assert.match(webAppSource, /ready-now/);
  assert.match(webAppSource, /soon-safe/);
  assert.match(webAppSource, /still-risky/);
  assert.match(webAppSource, /Action attente/);
  assert.match(webAppSource, /buildAtlasSelectedClimateFollowUpReadinessRecap/);
  assert.match(webAppSource, /renderAtlasSelectedClimateFollowUpReadinessRecap/);
  assert.match(webAppSource, /Readiness follow-up/);
  assert.match(webAppSource, /Récap readiness/);
  assert.match(webAppSource, /regional-fragility-conflict/);
  assert.match(webAppSource, /Action sûre/);
  assert.match(webAppSource, /Action à éviter/);
  assert.match(webAppSource, /buildAtlasNextClimateFollowUpAction/);
  assert.match(webAppSource, /renderAtlasNextClimateFollowUpAction/);
  assert.match(webAppSource, /Prochaine action climat/);
  assert.match(webAppSource, /Risque majeur évité/);
  assert.match(webAppSource, /Coût réserve\/tempo/);
  assert.match(webAppSource, /Follow-ups en attente/);
  assert.match(webAppSource, /Manque principal/);
  assert.match(webAppSource, /buildReadinessGapIndicator/);
  assert.match(webAppSource, /manque délai/);
  assert.match(webAppSource, /manque ressource/);
  assert.match(webAppSource, /manque région/);
  assert.match(webAppSource, /manque soutien/);
  assert.match(webAppSource, /manque à confirmer/);
  assert.match(webAppSource, /immediate-action/);
  assert.match(webAppSource, /safe-wait/);
  assert.match(webAppSource, /minimal-prep/);
  assert.match(webAppSource, /renderAtlasClimateReboundFollowUpQueue\(atlasClimateReboundFollowUpQueue\)\}\s*\$\{renderAtlasClimateFollowUpCompatibilityBundles\(atlasClimateFollowUpCompatibilityBundles\)\}\s*\$\{renderAtlasSelectedClimateFollowUpReadinessRecap\(atlasSelectedClimateFollowUpReadinessRecap\)\}\s*\$\{renderAtlasNextClimateFollowUpAction\(atlasNextClimateFollowUpAction\)\}/);

  assert.match(stylesSource, /\.map-world-climate-follow-up-compat/);
  assert.match(stylesSource, /\.map-world-climate-follow-up-compat__item--minimal-safe/);
  assert.match(stylesSource, /\.map-world-climate-follow-up-compat__item--ambitious-fragile/);
  assert.match(stylesSource, /\.map-world-climate-follow-up-readiness-recap/);
  assert.match(stylesSource, /\.map-world-climate-next-follow-up/);
  assert.match(stylesSource, /\.map-world-climate-next-follow-up__gap--resource/);
  assert.match(stylesSource, /\.map-world-climate-next-follow-up__gap--delay/);
  assert.match(stylesSource, /\.map-world-climate-next-follow-up__gap--region/);
  assert.match(stylesSource, /\.map-world-climate-next-follow-up__gap--support/);
  assert.match(stylesSource, /\.map-world-climate-next-follow-up__gap--fallback/);
});
